import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { Link } from 'react-router-dom';
import {
  getAdminOrders,
  getAdminProducts,
  getAdminUsers,
  updateAdminOrder,
  adminLogin,
  updateAdminUserRole,
  updateAdminUserDeleted,
  adminLogout
} from '../services/api';

// ===== Auto-logout (admin inactivity) configuration =====
const INACTIVITY_TIMEOUT_STORAGE_KEY = 'adminInactivityTimeoutKey';

/**
 * Timer options requested:
 *  - 15 sec, 30 sec, 1 min, 3 min, 5 min,
 *  - 15 min, 30 min, 1 hrs, 2 hrs, 3 hrs, 5 hrs,
 *  - off
 */
const TIMEOUT_OPTIONS = [
  { key: '15s', label: '15 sec', ms: 15_000 },
  { key: '30s', label: '30 sec', ms: 30_000 },
  { key: '1m', label: '1 min', ms: 60_000 },
  { key: '3m', label: '3 min', ms: 180_000 },
  { key: '5m', label: '5 min', ms: 300_000 },
  { key: '15m', label: '15 min', ms: 900_000 },
  { key: '30m', label: '30 min', ms: 1_800_000 },
  { key: '1h', label: '1 hr', ms: 3_600_000 },
  { key: '2h', label: '2 hrs', ms: 7_200_000 },
  { key: '3h', label: '3 hrs', ms: 10_800_000 },
  { key: '5h', label: '5 hrs', ms: 18_000_000 },
  { key: 'off', label: 'Off', ms: null }
];

const getTimeoutOption = (key) => TIMEOUT_OPTIONS.find((o) => o.key === key) || TIMEOUT_OPTIONS[5]; // default 15m

const getWarningThresholdMs = (timeoutMs) => {
  // Warn "near the end":
  // - at least 5s before expiry
  // - at most 2min before expiry
  // - proportional (20% of total)
  const proportional = Math.floor(timeoutMs * 0.2);
  return Math.min(120_000, Math.max(5_000, proportional));
};

const Admin = () => {

  const [activeTab, setActiveTab] = useState('orders');
  const [orders, setOrders] = useState([]);
  const [products, setProducts] = useState([]);
  const [users, setUsers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [isAdminAuthenticated, setIsAdminAuthenticated] = useState(false);
  const [loginForm, setLoginForm] = useState({ email: '', password: '' });
  const [loginError, setLoginError] = useState('');

  // ===== Auto-logout state =====
  const [timeoutKey, setTimeoutKey] = useState(() => {
    const stored = localStorage.getItem(INACTIVITY_TIMEOUT_STORAGE_KEY);
    return stored || '15m';
  });

  const timeoutOption = useMemo(() => getTimeoutOption(timeoutKey), [timeoutKey]);
  const inactivityTimeoutMs = timeoutOption.ms;

  const [remainingTimeMs, setRemainingTimeMs] = useState(
    inactivityTimeoutMs ?? 0
  );
  const [showWarning, setShowWarning] = useState(false);

  const lastActivityRef = useRef(Date.now());
  const countdownIntervalRef = useRef(null);

  const formatTime = useCallback((ms) => {
    if (ms == null || Number.isNaN(ms) || ms < 0) return '0:00';
    const seconds = Math.floor(ms / 1000);
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs < 10 ? '0' : ''}${secs}`;
  }, []);

  const clearCountdownInterval = useCallback(() => {
    if (countdownIntervalRef.current) {
      clearInterval(countdownIntervalRef.current);
      countdownIntervalRef.current = null;
    }
  }, []);

  const performAutoLogout = useCallback(() => {
    adminLogout();
    setIsAdminAuthenticated(false);
    setOrders([]);
    setProducts([]);
    setUsers([]);
    setShowWarning(false);
    setRemainingTimeMs(inactivityTimeoutMs ?? 0);

    clearCountdownInterval();
  }, [clearCountdownInterval, inactivityTimeoutMs]);

  const resetInactivityTimer = useCallback(() => {
    // If "Off", disable inactivity auto-logout.
    if (!inactivityTimeoutMs) {
      setRemainingTimeMs(0);
      setShowWarning(false);
      clearCountdownInterval();
      return;
    }

    lastActivityRef.current = Date.now();
    setRemainingTimeMs(inactivityTimeoutMs);
    setShowWarning(false);
  }, [clearCountdownInterval, inactivityTimeoutMs]);

  // Activity event handlers + countdown interval
  useEffect(() => {
    if (!isAdminAuthenticated) return;

    const handleActivity = () => {
      if (isAdminAuthenticated) resetInactivityTimer();
    };

    const events = ['mousemove', 'keydown', 'click', 'scroll', 'touchstart', 'touchmove'];
    events.forEach((event) => window.addEventListener(event, handleActivity));

    // Initialize/reset timer
    resetInactivityTimer();

    // Start 1s ticking countdown (so we can show countdown all the time)
    clearCountdownInterval();
    if (inactivityTimeoutMs) {
      countdownIntervalRef.current = setInterval(() => {
        const elapsed = Date.now() - lastActivityRef.current;
        const remaining = Math.max(0, inactivityTimeoutMs - elapsed);
        setRemainingTimeMs(remaining);

        if (remaining <= 0) {
          performAutoLogout();
          return;
        }

        const warningThresholdMs = getWarningThresholdMs(inactivityTimeoutMs);
        setShowWarning(remaining <= warningThresholdMs);
      }, 1000);
    }

    return () => {
      events.forEach((event) => window.removeEventListener(event, handleActivity));
      clearCountdownInterval();
      setShowWarning(false);
    };
  }, [clearCountdownInterval, inactivityTimeoutMs, isAdminAuthenticated, performAutoLogout, resetInactivityTimer]);

  // React to adminAuthChange from the 401 interceptor / other tabs
  useEffect(() => {
    const handleAuthChange = () => {
      const adminToken = localStorage.getItem('adminToken');
      if (!adminToken && isAdminAuthenticated) {
        performAutoLogout();
      }
    };

    window.addEventListener('adminAuthChange', handleAuthChange);
    return () => window.removeEventListener('adminAuthChange', handleAuthChange);
  }, [isAdminAuthenticated, performAutoLogout]);

  // When admin changes timer setting
  useEffect(() => {
    localStorage.setItem(INACTIVITY_TIMEOUT_STORAGE_KEY, timeoutKey);

    // Reset timer immediately for the current admin session
    if (isAdminAuthenticated) {
      resetInactivityTimer();
    }

    // Cleanup handled by resetInactivityTimer effect/interval logic
  }, [isAdminAuthenticated, resetInactivityTimer, timeoutKey]);

  useEffect(() => {
    // Check if admin is already logged in
    const adminToken = localStorage.getItem('adminToken');
    if (adminToken) {
      setIsAdminAuthenticated(true);
      fetchData();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleLogin = async (e) => {
    e.preventDefault();
    try {
      setLoginError('');
      const res = await adminLogin(loginForm);
      if (res.data && res.data.token) {
        setIsAdminAuthenticated(true);
        fetchData();
      }
    } catch (error) {
      setLoginError(error.response?.data?.message || 'Login failed');
    }
  };


  const fetchData = async () => {
    try {
      setLoading(true);
      const [ordersRes, productsRes, usersRes] = await Promise.all([
        getAdminOrders(),
        getAdminProducts(),
        getAdminUsers()
      ]);
      setOrders(ordersRes.data);
      setProducts(productsRes.data);
      setUsers(usersRes.data);
    } catch (error) {
      console.error('Error fetching data:', error);
      if (error.response?.status === 401) {
        performAutoLogout();
      }
    } finally {
      setLoading(false);
    }
  };

  const handleUpdateOrderStatus = async (orderId, status) => {
    try {
      await updateAdminOrder(orderId, { orderStatus: status });
      fetchData();
    } catch (error) {
      alert('Error updating order');
    }
  };

  const handleToggleUserAdmin = async (userId, nextIsAdmin) => {
    try {
      await updateAdminUserRole(userId, nextIsAdmin);
      fetchData();
    } catch (error) {
      alert('Error updating user role');
    }
  };

  const handleToggleUserDeleted = async (userId, nextIsDeleted) => {
    try {
      await updateAdminUserDeleted(userId, nextIsDeleted);
      fetchData();
    } catch (error) {
      alert('Error updating user status');
    }
  };

  const getStatusClass = (status) => {
    const classes = {
      processing: 'bg-blue-100 text-blue-800',
      confirmed: 'bg-indigo-100 text-indigo-800',
      shipped: 'bg-purple-100 text-purple-800',
      delivered: 'bg-green-100 text-green-800',
      cancelled: 'bg-red-100 text-red-800'
    };
    return classes[status] || 'bg-gray-100 text-gray-800';
  };

  const filteredOrders = orders.filter(
    (o) =>
      o._id.toLowerCase().includes(searchTerm.toLowerCase()) ||
      o.orderStatus.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredProducts = products.filter(
    (p) =>
      p.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
      p.category.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const filteredUsers = users.filter(
    (u) =>
      u.name?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      u.email?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const totalRevenue = orders
    .filter((o) => o.orderStatus !== 'cancelled')
    .reduce((sum, o) => sum + o.totalPrice, 0);

  const stats = [
    { label: 'Total Orders', value: orders.length, color: 'text-blue-600' },
    { label: 'Total Products', value: products.length, color: 'text-green-600' },
    { label: 'Total Users', value: users.length, color: 'text-purple-600' },
    { label: 'Revenue', value: `₹${totalRevenue}`, color: 'text-amber-600' }
  ];

  // Admin Login Form
  if (!isAdminAuthenticated) {
    return (
      <div className="fade-in flex items-center justify-center min-h-[60vh]">
        <div className="card p-8 w-full max-w-md">
          <h1 className="text-2xl font-bold text-center mb-6">Admin Login</h1>
          <p className="text-sm text-gray-600 text-center mb-6">Separate Admin Panel Database</p>

          {loginError && (
            <div className="bg-red-100 text-red-800 p-3 rounded mb-4 text-sm">{loginError}</div>
          )}

          <form onSubmit={handleLogin}>
            <div className="mb-4">
              <label className="block text-sm font-medium mb-2">Email</label>
              <input
                type="email"
                value={loginForm.email}
                onChange={(e) => setLoginForm({ ...loginForm, email: e.target.value })}
                className="input w-full"
                placeholder="admin@milkmitra.com"
                required
              />
            </div>

            <div className="mb-4">
              <label className="block text-sm font-medium mb-2">Password</label>
              <input
                type="password"
                value={loginForm.password}
                onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })}
                className="input w-full"
                placeholder="Enter password"
                required
              />
            </div>

            <button type="submit" className="btn btn-primary w-full">
              Login to Admin Panel
            </button>
          </form>

          <div className="mt-4 text-center text-sm text-gray-600">
            <Link to="/" className="text-primary-600 hover:underline">
              Back to Home
            </Link>
          </div>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="flex justify-center py-12">
        <div className="spinner" />
      </div>
    );
  }

  // Extend session (reset inactivity timer)
  const handleExtendSession = () => resetInactivityTimer();

  return (
    <div className="fade-in">
      {/* Auto logout warning modal */}
      {showWarning && inactivityTimeoutMs && (
        <div className="fixed inset-0 bg-black/40 dark:bg-black/60 flex items-center justify-center z-50">
          <div className="bg-white/90 dark:bg-gray-900/50 rounded-lg p-6 max-w-sm mx-4 shadow-xl border border-gray-200/70 dark:border-gray-800/60 backdrop-blur">
            <h3 className="text-lg font-bold text-gray-900 dark:text-gray-100 mb-2">Session Expiring Soon</h3>
            <p className="text-gray-800 dark:text-gray-200 mb-4">
              Your admin session will expire in{' '}
              <span className="font-bold text-red-600 dark:text-red-300">{formatTime(remainingTimeMs)}</span> due to inactivity.
            </p>
            <p className="text-sm text-gray-600 dark:text-gray-300 mb-4">Move your mouse, press a key, or click to stay logged in.</p>

            <div className="flex gap-2">
              <button onClick={handleExtendSession} className="btn btn-primary flex-1">
                Stay Logged In
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 mb-6 rounded-2xl border border-gray-200 dark:border-gray-800 bg-white/70 dark:bg-gray-900/40 backdrop-blur p-6">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-gray-100">Admin Dashboard</h1>
          <p className="text-gray-600 dark:text-gray-300">Separate Admin Database</p>
        </div>

        <div className="flex flex-col sm:flex-row items-start sm:items-center gap-3">
          <div className="flex items-center gap-3">
            <label className="text-sm font-medium text-gray-700 dark:text-gray-200">Auto-logout:</label>
            <select
              value={timeoutKey}
              onChange={(e) => setTimeoutKey(e.target.value)}
              className="text-sm border rounded px-3 py-2 bg-white/90 dark:bg-gray-900/60 dark:text-gray-100 dark:border-gray-700"
              aria-label="Select auto logout timer"
            >
              {TIMEOUT_OPTIONS.map((opt) => (
                <option key={opt.key} value={opt.key}>
                  {opt.label}
                </option>
              ))}
            </select>
          </div>

          {/* Always show countdown when timer is ON */}
          {inactivityTimeoutMs ? (
            <div className="text-sm text-gray-700 dark:text-gray-200">
              <span className="font-medium text-gray-900 dark:text-gray-100">Countdown:</span>{' '}
              <span
                className={`font-bold ${
                  showWarning ? 'text-red-600 dark:text-red-300' : 'text-gray-900 dark:text-gray-100'
                }`}
              >
                {formatTime(remainingTimeMs)}
              </span>
            </div>
          ) : (
            <div className="text-sm text-gray-700 dark:text-gray-200">
              <span className="font-medium text-gray-900 dark:text-gray-100">Countdown:</span> Off
            </div>
          )}

          {/* Logout button removed: admin logout is handled by Navbar */}
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        {stats.map((stat, index) => (
          <div key={index} className="card p-4 text-center">
            <p className={`text-2xl font-bold ${stat.color}`}>{stat.value}</p>
            <p className="text-sm text-gray-600 dark:text-gray-300">{stat.label}</p>
          </div>
        ))}
      </div>

      <div className="flex gap-2 mb-6 border-b border-gray-200 dark:border-gray-800">
        {['orders', 'products', 'users'].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 font-medium capitalize ${
              activeTab === tab
                ? 'border-b-2 border-primary-600 text-primary-700 dark:text-primary-300'
                : 'text-gray-600 hover:text-gray-800 dark:text-gray-300 dark:hover:text-white'
            }`}
          >
            {tab}
          </button>
        ))}
      </div>

      {/* Search + actions */}
      <div className="flex items-center gap-4 mb-6">
        <input
          type="text"
          placeholder="Search..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          className="input w-64"
        />
        <button onClick={fetchData} className="btn btn-secondary">
          Refresh
        </button>
      </div>

      {activeTab === 'orders' && (
          <div className="card overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-gray-800 dark:text-gray-100">
              <thead className="bg-gray-50 dark:bg-gray-800">
                <tr>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Order ID</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Items</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Total</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Status</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Date</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                {filteredOrders.slice(0, 10).map((order) => (
                  <tr key={order._id} className="hover:bg-gray-50 dark:hover:bg-gray-800/60">
                    <td className="px-4 py-3 text-sm">#{order._id.slice(-8)}</td>
                    <td className="px-4 py-3 text-sm">{order.totalItems} items</td>
                    <td className="px-4 py-3 text-sm">₹{order.totalPrice}</td>
                    <td className="px-4 py-3">
                      <span
                        className={`px-2 py-1 rounded-full text-xs ${getStatusClass(order.orderStatus)}`}
                      >
                        {order.orderStatus}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-sm">{new Date(order.createdAt).toLocaleDateString()}</td>
                    <td className="px-4 py-3">
                      <select
                        value={order.orderStatus}
                        onChange={(e) => handleUpdateOrderStatus(order._id, e.target.value)}
                        className="text-sm border rounded px-2 py-1 dark:bg-gray-900 dark:border-gray-700 dark:text-gray-100"
                      >
                        <option value="processing">Processing</option>
                        <option value="confirmed">Confirmed</option>
                        <option value="shipped">Shipped</option>
                        <option value="delivered">Delivered</option>
                        <option value="cancelled">Cancelled</option>
                      </select>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {filteredOrders.length === 0 && <div className="p-8 text-center text-gray-600 dark:text-gray-400">No orders found</div>}
        </div>
      )}

      {activeTab === 'products' && (
          <div className="card overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-gray-800 dark:text-gray-100">
              <thead className="bg-gray-50 dark:bg-gray-800">
                <tr>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Product</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Category</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Price</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Stock</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                {filteredProducts.slice(0, 10).map((product) => (
                  <tr key={product._id} className="hover:bg-gray-50 dark:hover:bg-gray-800/60">
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-3">
                        {product.image && (
                          <img
                            src={product.image}
                            alt={product.name}
                            className="w-10 h-10 object-cover rounded"
                          />
                        )}
                        <span className="font-medium">{product.name}</span>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-sm capitalize">{product.category}</td>
                    <td className="px-4 py-3 text-sm">
                      ₹{product.price}/{product.unit}
                    </td>
                    <td className="px-4 py-3 text-sm">{product.stock}</td>
                    <td className="px-4 py-3">
                      <span
                        className={`px-2 py-1 rounded-full text-xs ${
                          product.stock > 0 ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
                        }`}
                      >
                        {product.stock > 0 ? 'In Stock' : 'Out of Stock'}
                      </span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {filteredProducts.length === 0 && <div className="p-8 text-center text-gray-600 dark:text-gray-400">No products found</div>}
        </div>
      )}

      {activeTab === 'users' && (
          <div className="card overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-gray-800 dark:text-gray-100">
              <thead className="bg-gray-50 dark:bg-gray-800">
                <tr>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Name</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Email</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Role</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Joined</th>
                  <th className="px-4 py-3 text-left text-sm font-semibold">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-200 dark:divide-gray-700">
                {filteredUsers.slice(0, 10).map((user) => (
                  <tr key={user._id} className="hover:bg-gray-50 dark:hover:bg-gray-800/60">
                    <td className="px-4 py-3 text-sm">{user.name}</td>
                    <td className="px-4 py-3 text-sm">{user.email}</td>
                    <td className="px-4 py-3">
                      <span
                        className={`px-2 py-1 rounded-full text-xs ${
                          user.isAdmin
                            ? 'bg-purple-100 text-purple-800 dark:bg-purple-900/30 dark:text-purple-200'
                            : 'bg-gray-100 text-gray-800 dark:bg-gray-700/40 dark:text-gray-200'
                        }`}
                      >
                        {user.isAdmin ? 'admin' : 'user'}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-sm">{new Date(user.createdAt).toLocaleDateString()}</td>
                    <td className="px-4 py-3">
                      <div className="flex flex-col sm:flex-row gap-2">
                        <button
                          className="btn btn-secondary text-xs px-2 py-1"
                          onClick={() => handleToggleUserAdmin(user._id, !user.isAdmin)}
                        >
                          {user.isAdmin ? 'Set User' : 'Set Admin'}
                        </button>

                        <button
                          className={`btn text-xs px-2 py-1 ${user.isDeleted ? 'btn-primary' : 'btn-secondary'}`}
                          onClick={() => handleToggleUserDeleted(user._id, !user.isDeleted)}
                        >
                          {user.isDeleted ? 'Restore' : 'Soft Delete'}
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {filteredUsers.length === 0 && <div className="p-8 text-center text-gray-600 dark:text-gray-400">No users found</div>}
        </div>
      )}
    </div>
  );
};

export default Admin;
